script:
(function () {
  'use strict';
  // Borrowing to invest: leveraged plan vs. investing only your own money.
  // Leveraged: own money + loan - upfront loan costs is invested and grows monthly at
  //   (1 + r)^(1/12) - 1. Loan interest accrues at rate / 12 a month and is handled one of three ways:
  //   interest-only (you pay the interest each month, principal repaid from the investment at the end),
  //   amortizing (you pay the level monthly payment), or added to the loan (margin-style, nothing paid).
  //   Your equity at the end = investment value - loan balance still owed.
  // Unleveraged (fair comparison): your own money is invested and every monthly loan payment you
  //   would have made is invested instead, at the end of each month.
  // Break-even return: the annual return at which both plans end equal (found by bisection).
  // Your return: money-weighted annual return on what you put in (own money + loan payments).
  // Verified (Node, scratch tests): with no upfront costs the break-even return equals the loan's
  // effective annual rate, (1 + 8%/12)^12 - 1 = 8.30%, in all three repayment modes; amortizing
  // payment on $50,000 at 8% for 10 years = $606.64 (standard amortization formula); interest added
  // to the loan: $50,000 at 8% for 10 years owes 50,000 x (1 + 0.08/12)^120 = $110,982.01;
  // the unleveraged plan's money-weighted return equals the investment return.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  // --- calc start
  function payment(loan, i, n) {
    if (n < 1) return 0;
    return Math.abs(i) < 1e-12 ? loan / n : loan * i / (1 - Math.pow(1 + i, -n));
  }

  function simulate(p) {
    var n = p.years * 12, i = p.loanRate / 12, g = Math.pow(1 + p.rate, 1 / 12) - 1;
    var pay = p.mode === 'io' ? p.loan * i : p.mode === 'amort' ? payment(p.loan, i, n) : 0;
    var inv = p.own + p.loan - p.fee, debt = p.loan, alt = p.own, interest = 0, rows = [];
    for (var m = 1; m <= n; m++) {
      inv *= 1 + g;
      var accrued = debt * i;
      interest += accrued;
      if (p.mode === 'accrue') debt += accrued;
      else if (p.mode === 'amort') debt = debt + accrued - pay;
      if (Math.abs(debt) < 1e-6) debt = 0;
      alt = alt * (1 + g) + pay;
      if (m % 12 === 0) rows.push({ year: m / 12, inv: inv, debt: debt, equity: inv - debt, alt: alt });
    }
    return { inv: inv, debt: debt, equity: inv - debt, alt: alt, interest: interest, pay: pay,
             paid: pay * n, rows: rows };
  }

  // Money-weighted annual return on own money paid at the start plus `pay` each month.
  function moneyReturn(own, pay, n, ending) {
    if (ending <= 0 || own + pay <= 0 || n < 1) return null;
    function fv(i) {
      var f = Math.pow(1 + i, n);
      return own * f + pay * (Math.abs(i) < 1e-12 ? n : (f - 1) / i);
    }
    var lo = -0.9, hi = 1;
    if (fv(lo) > ending || fv(hi) < ending) return null;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (fv(mid) < ending) lo = mid; else hi = mid;
    }
    return Math.pow(1 + (lo + hi) / 2, 12) - 1;
  }

  // Annual return at which leveraged equity equals the unleveraged value.
  function breakEven(p) {
    function diff(r) {
      var q = {}; for (var k in p) q[k] = p[k];
      q.rate = r;
      var s = simulate(q);
      return s.equity - s.alt;
    }
    var lo = -0.9, hi = 2, dlo = diff(lo), dhi = diff(hi);
    if (dlo > 0 || dhi < 0) return null;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (diff(mid) < 0) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function setText(id, text) { document.getElementById(id).textContent = text; }
  function pct(v) { return (Math.abs(v) < 5e-7 ? 0 : v * 100).toFixed(2) + '%'; }
  function signed(v) { return (v < 0 ? '−' : '+') + money.format(Math.abs(v)); }

  function update() {
    var p = { loan: num('ilLoan'), own: num('ilOwn'), loanRate: num('ilLoanRate'), rate: num('ilReturn'),
              years: Math.round(num('ilYears')), fee: num('ilFee'), mode: document.getElementById('ilMode').value };
    var error = document.getElementById('ilError');
    var bad = [p.loan, p.own, p.loanRate, p.rate, p.years, p.fee].some(isNaN) || p.loan <= 0 || p.own < 0 ||
              p.loanRate < 0 || p.loanRate > 50 || p.rate < -50 || p.rate > 50 || p.years < 1 || p.years > 40 ||
              p.fee < 0 || p.fee >= p.own + p.loan;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a loan above $0, your own money of $0 or more, a loan rate from 0% to 50%, a return from -50% to 50%, 1 to 40 years, and upfront costs below the amount invested.';
      return;
    }
    p.loanRate /= 100;
    p.rate /= 100;
    var s = simulate(p);
    var gain = s.equity - s.alt;
    setText('ilEquity', money.format(s.equity));
    setText('ilAlt', money.format(s.alt));
    setText('ilGain', signed(gain));
    var be = breakEven(p);
    setText('ilBreakEven', be === null ? '–' : pct(be));
    setText('ilInterest', money.format(s.interest));
    setText('ilPay', s.pay > 0 ? money.format(s.pay) + ' a month' : 'None until the end');
    setText('ilPaid', money.format(s.paid));
    setText('ilOwed', money.format(s.debt));
    setText('ilInvested', money.format(s.inv));
    var mr = moneyReturn(p.own, s.pay, p.years * 12, s.equity);
    setText('ilMyReturn', s.equity <= 0 ? 'Everything you put in was lost' : p.own + s.pay <= 0 ? 'None of your own money went in' : mr === null ? '–' : pct(mr));
    setText('ilVerdict', (gain >= 0 ? 'Borrowing comes out ' + money.format(gain) + ' ahead' :
      'Borrowing leaves you ' + money.format(-gain) + ' behind') + ' with a yearly return of ' + pct(p.rate) + '.' + (be === null ? '' :
      ' The two plans break even at a yearly return of ' + pct(be) + '; below that, the loan costs more than it earns.'));
    document.getElementById('ilWarn').hidden = s.equity >= 0;

    var rates = [-0.2, -0.1, 0, 0.05, 0.1, 0.15];
    if (rates.every(function (r) { return Math.abs(r - p.rate) > 1e-9; })) rates.push(p.rate);
    rates.sort(function (a, b) { return a - b; });
    document.getElementById('ilWhatIf').innerHTML = rates.map(function (r) {
      var q = {}; for (var k in p) q[k] = p[k];
      q.rate = r;
      var t = simulate(q);
      return '<tr><td>' + pct(r) + (Math.abs(r - p.rate) < 1e-9 ? ' (yours)' : '') + '</td><td>' + money.format(t.equity) +
        '</td><td>' + money.format(t.alt) + '</td><td>' + signed(t.equity - t.alt) + '</td></tr>';
    }).join('');
    document.getElementById('ilSchedule').innerHTML = s.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.inv) + '</td><td>' + money.format(row.debt) +
        '</td><td>' + money.format(row.equity) + '</td><td>' + money.format(row.alt) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ilForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
